#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int u, v, w;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int E, R;
    cin >> E >> R;

    vector<Edge> edges(R);
    vector<vector<pair<int, int>>> graph(E);

    for (int i = 0; i < R; ++i) {
        int a, b, c;
        cin >> a >> b >> c;
        --a;
        --b;
        edges[i] = {a, b, c};
        graph[a].push_back({b, i});
        graph[b].push_back({a, i});
    }

    vector<int> tin(E, -1), low(E, -1);
    vector<char> isBridge(R, false);
    int timer = 0;

    function<void(int, int)> dfs = [&](int v, int parentEdge) {
        tin[v] = low[v] = timer++;
        for (auto [to, id] : graph[v]) {
            if (id == parentEdge) continue;
            if (tin[to] != -1) {
                low[v] = min(low[v], tin[to]);
            } else {
                dfs(to, id);
                low[v] = min(low[v], low[to]);
                if (low[to] > tin[v]) isBridge[id] = true;
            }
        }
    };

    for (int v = 0; v < E; ++v) {
        if (tin[v] == -1) dfs(v, -1);
    }

    vector<long long> cycleLength(E, 0);
    vector<char> visited(E, false), countedEdge(R, false);

    for (int start = 0; start < E; ++start) {
        bool hasCycleEdge = false;
        for (auto [to, id] : graph[start]) {
            if (!isBridge[id]) {
                hasCycleEdge = true;
                break;
            }
        }
        if (!hasCycleEdge || visited[start]) continue;

        vector<int> vertices;
        stack<int> st;
        st.push(start);
        visited[start] = true;
        long long length = 0;

        while (!st.empty()) {
            int v = st.top();
            st.pop();
            vertices.push_back(v);

            for (auto [to, id] : graph[v]) {
                if (isBridge[id]) continue;
                if (!countedEdge[id]) {
                    countedEdge[id] = true;
                    length += edges[id].w;
                }
                if (!visited[to]) {
                    visited[to] = true;
                    st.push(to);
                }
            }
        }

        for (int v : vertices) cycleLength[v] = length;
    }

    int K;
    cin >> K;

    const long long INF = (1LL << 60);

    while (K--) {
        int x;
        long long T;
        cin >> x >> T;
        --x;

        vector<long long> dist(E, INF);
        priority_queue<pair<long long, int>,
                       vector<pair<long long, int>>,
                       greater<pair<long long, int>>> pq;

        for (int v = 0; v < E; ++v) {
            if (cycleLength[v] >= T) {
                dist[v] = cycleLength[v];
                pq.push({dist[v], v});
            }
        }

        while (!pq.empty()) {
            auto [d, v] = pq.top();
            pq.pop();
            if (d != dist[v]) continue;

            for (auto [to, id] : graph[v]) {
                long long nd = d + 2LL * edges[id].w;
                if (nd < dist[to]) {
                    dist[to] = nd;
                    pq.push({nd, to});
                }
            }
        }

        cout << (dist[x] == INF ? -1 : dist[x]) << '\n';
    }

    return 0;
}
